PythonExport.ClassDeclarations:
public:
    /// Become a live view of \a prop, which registers this object with it
    void attach(PropertyAppearanceList *prop);
    /// Stop being one, keeping the value as it stands (a shared snapshot).
    /// Called by the property when it dies, and by any assignment that
    /// hands this list to a new owner.
    void detachFromOwner();
    /// The property this is a view of, or null once detached
    PropertyAppearanceList *getOwner() const { return owner; }
    /// The value, wherever it lives: the owner's while attached, this
    /// object's own once detached
    const AppearanceList &list() const;

    /// Run a write, through the owner's change signalling while attached
    void edit(const std::function<void(AppearanceList &)> &op, int touched = -1);

private:
    /// Whether a write is allowed at all, i.e. the object is alive and not
    /// const. Raises and answers false when it is not.
    bool writable();

    /** @name The shared bodies of the per field accessors
     *
     * Each takes the member it is to call, with that member's own type. A
     * pointer to member function is two words on this ABI -- the entry
     * point and the this-adjustment -- so it must not travel as a void *:
     * the adjustment would be dropped on the way in, read back off
     * whatever followed the argument on the way out, and added to this.
     */
    //@{
    using ColorGetter = Color (AppearanceList::*)(int) const;
    using ColorSetter = void (AppearanceList::*)(int, const Color &);
    using ColorAllSetter = void (AppearanceList::*)(const Color &);
    using FloatGetter = float (AppearanceList::*)(int) const;
    using FloatSetter = void (AppearanceList::*)(int, float);
    using FloatAllSetter = void (AppearanceList::*)(float);

    PyObject *colorGet(PyObject *args, ColorGetter getter);
    PyObject *colorSet(PyObject *args, ColorSetter setter, ColorAllSetter allsetter);
    PyObject *floatGet(PyObject *args, FloatGetter getter);
    PyObject *floatSet(PyObject *args, FloatSetter setter, FloatAllSetter allsetter);
    /// The (index, slot, value) an argument list states; no index answers
    /// -1, which the texture writers read as "every entry"
    bool textureArgs(PyObject *args, const char *format, int &idx, uint8_t &slot,
                     const char *&value);
    /// Run a write over one entry's texture record, or over every entry's
    void editTexture(int idx, const std::function<void(SurfaceTexture &)> &op);
    //@}

    PropertyAppearanceList *owner = nullptr;
    AppearanceList *ownvalue = nullptr;
